------ Para probar que si sirve (ojala y si)
---- De aquí para abajo es pura verificación, no quiero mas errores con datos.

SELECT year, value
FROM economic_data e
JOIN indicators i ON e.series_code = i.series_code
JOIN countries c ON e.country_code = c.country_code
WHERE c.country_name = 'Brazil' 
AND i.series_name = 'GDP per capita (current US$)'
ORDER BY year;

-- Verifica GDP growth de Brasil (el otro indicador que sabíamos estaba roto)
SELECT year, value
FROM economic_data e
JOIN indicators i ON e.series_code = i.series_code
JOIN countries c ON e.country_code = c.country_code
WHERE c.country_name = 'Brazil' AND i.series_name = 'GDP growth (annual %)'
ORDER BY year;

-- Verifica que ningun valor quedó en NULL por error del UPDATE
SELECT country_name, series_name, COUNT(*) as filas_null
FROM economic_data e
JOIN indicators i ON e.series_code = i.series_code
JOIN countries c ON e.country_code = c.country_code
WHERE e.value IS NULL
GROUP BY country_name, series_name;

-- Alemania: GDP per cápita (debería verse en miles de USD, sin saltos raros)
SELECT year, value
FROM economic_data e
JOIN indicators i ON e.series_code = i.series_code
JOIN countries c ON e.country_code = c.country_code
WHERE c.country_name = 'Germany' AND i.series_name = 'GDP per capita (current US$)'
ORDER BY year;

-- Rusia: Inflation (debería tener valores razonables en %, sin saltos abruptos de escala)
SELECT year, value
FROM economic_data e
JOIN indicators i ON e.series_code = i.series_code
JOIN countries c ON e.country_code = c.country_code
WHERE c.country_name = 'Russian Federation' AND i.series_name = 'Inflation, consumer prices (annual %)'
ORDER BY year;

-- Sudáfrica: Unemployment (debería estar en rango de 20-35%, típico de Sudáfrica)

SELECT DISTINCT country_name FROM countries;
SELECT DISTINCT series_name FROM indicators WHERE series_name ILIKE '%unemploy%';





SELECT year, value
FROM economic_data e
JOIN indicators i ON e.series_code = i.series_code
JOIN countries c ON e.country_code = c.country_code
WHERE c.country_name = 'South Africa' AND i.series_name = 'Unemployment, total (% of total labor force)'
ORDER BY year;



















